CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS aurora;
SET search_path = aurora, public;
CREATE TABLE tenant (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE company (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), code text NOT NULL CHECK(code IN ('COREVIA','MASIL','AURORA','CELTONIC')), name text NOT NULL, UNIQUE(tenant_id,code), UNIQUE(tenant_id,id));
CREATE TABLE principal (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), issuer text NOT NULL, subject text NOT NULL, kind text NOT NULL CHECK(kind IN ('REAL','MOCK','SERVICE')), enabled boolean NOT NULL DEFAULT true, UNIQUE(issuer,subject), UNIQUE(tenant_id,id));
CREATE TABLE company_role (tenant_id uuid NOT NULL, company_id uuid NOT NULL, principal_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('VIEWER','ANALYST','SCM','QUALITY_COMMITTEE','SALES_SUPPORT','SALES_EXECUTIVE','MARKETING','MASIL_CEO','GROUP_CEO_BOARD','MOCK_COORDINATOR','WORKER')), PRIMARY KEY(tenant_id,company_id,principal_id,role), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id), FOREIGN KEY(tenant_id,principal_id) REFERENCES principal(tenant_id,id));
CREATE TABLE auth_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), principal_id uuid NOT NULL, token_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, FOREIGN KEY(tenant_id,principal_id) REFERENCES principal(tenant_id,id));
CREATE TABLE source_document (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, source_ref text NOT NULL, sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'), media_type text NOT NULL, classification text NOT NULL CHECK(classification IN ('FACT_SOURCE','AUTHOR_CLAIM')), observed_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id), UNIQUE(tenant_id,company_id,source_ref,sha256), UNIQUE(tenant_id,company_id,id));
-- row_id is original primary key, or documented physical 1-based data row for non-key files.
CREATE TABLE intake_row (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, document_id uuid NOT NULL, source_ref text NOT NULL, row_id text NOT NULL, raw_record jsonb NOT NULL CHECK(jsonb_typeof(raw_record)='object'), raw_line text NOT NULL, valid_at date, observed_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,company_id,document_id) REFERENCES source_document(tenant_id,company_id,id), UNIQUE(document_id,row_id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE business_case (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','WAITING_INFORMATION','WAITING_APPROVAL','EXECUTING','BLOCKED','READY_TO_CLOSE','CLOSED')), version integer NOT NULL DEFAULT 1 CHECK(version>0), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id), FOREIGN KEY(tenant_id,created_by) REFERENCES principal(tenant_id,id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE assumption (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, case_id uuid NOT NULL, statement text NOT NULL, valid_until timestamptz, accepted_by uuid, FOREIGN KEY(tenant_id,company_id,case_id) REFERENCES business_case(tenant_id,company_id,id), FOREIGN KEY(tenant_id,accepted_by) REFERENCES principal(tenant_id,id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, case_id uuid NOT NULL, classification text NOT NULL CHECK(classification IN ('FACT_SOURCE','CALCULATED','AUTHOR_CLAIM','ASSUMPTION','SIMULATED_EVENT')), source_row_id uuid, assumption_id uuid, source_ref text NOT NULL, row_id text NOT NULL, valid_at timestamptz, observed_at timestamptz NOT NULL, value jsonb NOT NULL, formula_version text, content_hash text NOT NULL CHECK(content_hash ~ '^[a-f0-9]{64}$'), supersedes_id uuid, FOREIGN KEY(tenant_id,company_id,case_id) REFERENCES business_case(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,source_row_id) REFERENCES intake_row(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,assumption_id) REFERENCES assumption(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,supersedes_id) REFERENCES evidence(tenant_id,company_id,id), CHECK(classification NOT IN ('FACT_SOURCE','AUTHOR_CLAIM') OR source_row_id IS NOT NULL), CHECK(classification<>'ASSUMPTION' OR assumption_id IS NOT NULL), CHECK(classification<>'CALCULATED' OR formula_version IS NOT NULL), UNIQUE(tenant_id,company_id,id));
CREATE TABLE evidence_lineage (tenant_id uuid NOT NULL, company_id uuid NOT NULL, child_id uuid NOT NULL, parent_id uuid NOT NULL, PRIMARY KEY(child_id,parent_id), CHECK(child_id<>parent_id), FOREIGN KEY(tenant_id,company_id,child_id) REFERENCES evidence(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,parent_id) REFERENCES evidence(tenant_id,company_id,id));
CREATE TABLE policy_snapshot (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, policy_version text NOT NULL, digest text NOT NULL CHECK(digest ~ '^[a-f0-9]{64}$'), quality_row_id uuid NOT NULL, authority_row_id uuid NOT NULL, calculation_row_id uuid NOT NULL, covenant_row_id uuid, compiled_rules jsonb NOT NULL CHECK(jsonb_typeof(compiled_rules)='object' AND compiled_rules <> '{}'::jsonb), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,quality_row_id) REFERENCES intake_row(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,authority_row_id) REFERENCES intake_row(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,calculation_row_id) REFERENCES intake_row(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,covenant_row_id) REFERENCES intake_row(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE ai_run (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, case_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','AI_NOT_CONFIGURED','DEGRADED','FAILED')), model text, provider_request_id text, prompt_hash text NOT NULL, input_evidence_ids uuid[] NOT NULL DEFAULT '{}', output jsonb, error_code text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, FOREIGN KEY(tenant_id,company_id,case_id) REFERENCES business_case(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE action_plan (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, case_id uuid NOT NULL, revision integer NOT NULL CHECK(revision>0), supersedes_id uuid, ai_run_id uuid, policy_snapshot_id uuid NOT NULL, state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','NEEDS_INFORMATION','PENDING_APPROVAL','APPROVED','REJECTED','SUPERSEDED','EXECUTING','COMPLETED')), version integer NOT NULL DEFAULT 1 CHECK(version>0), plan_hash text NOT NULL CHECK(plan_hash ~ '^[a-f0-9]{64}$'), structured_plan jsonb NOT NULL CHECK(jsonb_typeof(structured_plan)='object'), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,case_id) REFERENCES business_case(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,supersedes_id) REFERENCES action_plan(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,ai_run_id) REFERENCES ai_run(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,policy_snapshot_id) REFERENCES policy_snapshot(tenant_id,company_id,id), UNIQUE(case_id,revision), UNIQUE(tenant_id,company_id,id));
CREATE UNIQUE INDEX one_current_plan ON action_plan(case_id) WHERE state <> 'SUPERSEDED';
CREATE TABLE plan_action (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, plan_id uuid NOT NULL, action_key text NOT NULL, kind text NOT NULL CHECK(kind IN ('INVESTIGATE','REQUEST_INFORMATION','RECALL','PURCHASE_ORDER','SHIPMENT','RETURN_RECEIPT','DISPOSAL','REPLACEMENT','REGULATORY_REVIEW','ADVERSE_EVENT_REVIEW','CAPA','NOTICE')), target_ref text NOT NULL CHECK(length(target_ref)>0), quantity integer NOT NULL CHECK(quantity>0), amount_krw bigint NOT NULL DEFAULT 0 CHECK(amount_krw>=0), cash_out_date date, due_at timestamptz NOT NULL, scope_hash text NOT NULL CHECK(scope_hash ~ '^[a-f0-9]{64}$'), FOREIGN KEY(tenant_id,company_id,plan_id) REFERENCES action_plan(tenant_id,company_id,id), UNIQUE(plan_id,action_key), UNIQUE(tenant_id,company_id,id));
CREATE TABLE plan_evidence (tenant_id uuid NOT NULL, company_id uuid NOT NULL, plan_id uuid NOT NULL, evidence_id uuid NOT NULL, PRIMARY KEY(plan_id,evidence_id), FOREIGN KEY(tenant_id,company_id,plan_id) REFERENCES action_plan(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,evidence_id) REFERENCES evidence(tenant_id,company_id,id));
CREATE TABLE approval_requirement (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, plan_id uuid NOT NULL, action_id uuid NOT NULL, authority text NOT NULL CHECK(authority IN ('SCM','QUALITY_COMMITTEE','SALES_SUPPORT','SALES_EXECUTIVE','MARKETING','MASIL_CEO','GROUP_CEO_BOARD')), policy_rule text NOT NULL, FOREIGN KEY(tenant_id,company_id,plan_id) REFERENCES action_plan(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,action_id) REFERENCES plan_action(tenant_id,company_id,id), UNIQUE(action_id,authority), UNIQUE(tenant_id,company_id,id));
CREATE TABLE approval_scope (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, requirement_id uuid NOT NULL UNIQUE, plan_id uuid NOT NULL, action_id uuid NOT NULL, revision integer NOT NULL CHECK(revision>0), scope_hash text NOT NULL, max_quantity integer NOT NULL CHECK(max_quantity>0), reserved_quantity integer NOT NULL DEFAULT 0 CHECK(reserved_quantity>=0), consumed_quantity integer NOT NULL DEFAULT 0 CHECK(consumed_quantity>=0), max_amount_krw bigint NOT NULL CHECK(max_amount_krw>=0), reserved_amount_krw bigint NOT NULL DEFAULT 0 CHECK(reserved_amount_krw>=0), consumed_amount_krw bigint NOT NULL DEFAULT 0 CHECK(consumed_amount_krw>=0), expires_at timestamptz NOT NULL, state text NOT NULL CHECK(state IN ('PENDING','APPROVED','REJECTED','REVOKED','EXPIRED')), CHECK(reserved_quantity::bigint+consumed_quantity<=max_quantity), CHECK(reserved_amount_krw::numeric+consumed_amount_krw<=max_amount_krw), FOREIGN KEY(tenant_id,company_id,requirement_id) REFERENCES approval_requirement(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,plan_id) REFERENCES action_plan(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,action_id) REFERENCES plan_action(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE approval_decision (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, scope_id uuid NOT NULL, principal_id uuid NOT NULL, decision text NOT NULL CHECK(decision IN ('APPROVE','REJECT')), comment text NOT NULL CHECK(length(comment)>0), session_id uuid NOT NULL REFERENCES auth_session(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,scope_id) REFERENCES approval_scope(tenant_id,company_id,id), FOREIGN KEY(tenant_id,principal_id) REFERENCES principal(tenant_id,id), UNIQUE(scope_id));
CREATE TABLE task (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, case_id uuid NOT NULL, plan_id uuid NOT NULL, action_id uuid NOT NULL, business_key text NOT NULL, kind text NOT NULL, state text NOT NULL CHECK(state IN ('PENDING','BLOCKED','READY','RUNNING','WAITING_RESPONSE','UNKNOWN','SUCCEEDED','REJECTED','CANCELLED','FAILED')), mandatory boolean NOT NULL DEFAULT true, due_at timestamptz NOT NULL, next_attempt_at timestamptz, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), result_evidence_id uuid, version integer NOT NULL DEFAULT 1 CHECK(version>0), FOREIGN KEY(tenant_id,company_id,case_id) REFERENCES business_case(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,plan_id) REFERENCES action_plan(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,action_id) REFERENCES plan_action(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,result_evidence_id) REFERENCES evidence(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,business_key), UNIQUE(tenant_id,company_id,id));
CREATE TABLE task_dependency (tenant_id uuid NOT NULL, company_id uuid NOT NULL, task_id uuid NOT NULL, depends_on_id uuid NOT NULL, PRIMARY KEY(task_id,depends_on_id), CHECK(task_id<>depends_on_id), FOREIGN KEY(tenant_id,company_id,task_id) REFERENCES task(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,depends_on_id) REFERENCES task(tenant_id,company_id,id));
CREATE TABLE timer (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, task_id uuid NOT NULL, timer_key text NOT NULL, fire_at timestamptz NOT NULL, fired_at timestamptz, state text NOT NULL DEFAULT 'SCHEDULED' CHECK(state IN ('SCHEDULED','FIRED','CANCELLED')), FOREIGN KEY(tenant_id,company_id,task_id) REFERENCES task(tenant_id,company_id,id), UNIQUE(task_id,timer_key), UNIQUE(tenant_id,company_id,id));
CREATE TABLE command (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, task_id uuid NOT NULL, action_id uuid NOT NULL, plan_id uuid NOT NULL, business_key text NOT NULL, request_hash text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), amount_krw bigint NOT NULL CHECK(amount_krw>=0), state text NOT NULL CHECK(state IN ('ACCEPTED','DISPATCHING','WAITING_RESPONSE','SUCCEEDED','REJECTED','UNKNOWN','CANCELLED')), adapter text NOT NULL DEFAULT 'MOCK' CHECK(adapter='MOCK'), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,task_id) REFERENCES task(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,action_id) REFERENCES plan_action(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,plan_id) REFERENCES action_plan(tenant_id,company_id,id), FOREIGN KEY(tenant_id,created_by) REFERENCES principal(tenant_id,id), UNIQUE(tenant_id,company_id,business_key), UNIQUE(tenant_id,company_id,id));
CREATE TABLE approval_usage (tenant_id uuid NOT NULL, company_id uuid NOT NULL, scope_id uuid NOT NULL, command_id uuid NOT NULL, quantity integer NOT NULL CHECK(quantity>0), amount_krw bigint NOT NULL CHECK(amount_krw>=0), state text NOT NULL CHECK(state IN ('RESERVED','CONSUMED','RELEASED')), PRIMARY KEY(scope_id,command_id), FOREIGN KEY(tenant_id,company_id,scope_id) REFERENCES approval_scope(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,command_id) REFERENCES command(tenant_id,company_id,id));
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, command_id uuid NOT NULL, topic text NOT NULL CHECK(topic='MOCK_COMMAND'), payload jsonb NOT NULL, state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','LEASED','DELIVERED','UNKNOWN','DEAD')), available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), FOREIGN KEY(tenant_id,company_id,command_id) REFERENCES command(tenant_id,company_id,id), UNIQUE(command_id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, provider text NOT NULL CHECK(provider='MOCK'), event_id text NOT NULL, business_key text NOT NULL, command_id uuid NOT NULL, payload_hash text NOT NULL, payload jsonb NOT NULL, applied_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,command_id) REFERENCES command(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,provider,event_id), UNIQUE(tenant_id,company_id,provider,business_key), UNIQUE(tenant_id,company_id,id));
CREATE TABLE quantity_account (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, case_id uuid NOT NULL, target_ref text NOT NULL, shipped_qty integer NOT NULL CHECK(shipped_qty>=0), received_qty integer NOT NULL DEFAULT 0 CHECK(received_qty>=0 AND received_qty<=shipped_qty), disposed_qty integer NOT NULL DEFAULT 0 CHECK(disposed_qty>=0 AND disposed_qty<=received_qty), replaced_qty integer NOT NULL DEFAULT 0 CHECK(replaced_qty>=0 AND replaced_qty<=shipped_qty), version integer NOT NULL DEFAULT 1 CHECK(version>0), FOREIGN KEY(tenant_id,company_id,case_id) REFERENCES business_case(tenant_id,company_id,id), UNIQUE(case_id,target_ref), UNIQUE(tenant_id,company_id,id));
CREATE TABLE quantity_movement (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, account_id uuid NOT NULL, inbox_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('RETURN_RECEIPT','DISPOSAL','REPLACEMENT')), quantity integer NOT NULL CHECK(quantity>0), business_key text NOT NULL, FOREIGN KEY(tenant_id,company_id,account_id) REFERENCES quantity_account(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,inbox_id) REFERENCES inbox(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,business_key));
-- Signed balances can be negative; amounts of individual obligations/commands cannot.
CREATE TABLE cash_day (tenant_id uuid NOT NULL, company_id uuid NOT NULL, cash_date date NOT NULL, baseline_closing_krw bigint NOT NULL, reserved_krw bigint NOT NULL DEFAULT 0 CHECK(reserved_krw>=0), simulated_paid_krw bigint NOT NULL DEFAULT 0 CHECK(simulated_paid_krw>=0), forecast_evidence_id uuid NOT NULL, version integer NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,company_id,cash_date), FOREIGN KEY(tenant_id,company_id,forecast_evidence_id) REFERENCES evidence(tenant_id,company_id,id));
CREATE TABLE payment_obligation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, counterparty_ref text NOT NULL, invoice_ref text NOT NULL, installment_ref text NOT NULL DEFAULT 'FULL', due_date date NOT NULL, amount_krw bigint NOT NULL CHECK(amount_krw>0), command_id uuid, state text NOT NULL CHECK(state IN ('OPEN','RESERVED','SIMULATED_PAID','REJECTED','UNKNOWN')), source_evidence_id uuid NOT NULL, FOREIGN KEY(tenant_id,company_id,command_id) REFERENCES command(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,source_evidence_id) REFERENCES evidence(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,counterparty_ref,invoice_ref,installment_ref), UNIQUE(tenant_id,company_id,id));
CREATE TABLE idempotency_record (tenant_id uuid NOT NULL, company_id uuid NOT NULL, principal_id uuid NOT NULL, method text NOT NULL, route text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), request_hash text NOT NULL, http_status integer CHECK(http_status BETWEEN 200 AND 599), response_body jsonb, response_etag text, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,company_id,principal_id,method,route,key), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id), FOREIGN KEY(tenant_id,principal_id) REFERENCES principal(tenant_id,id));
CREATE TABLE mock_scenario (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, code text NOT NULL CHECK(code IN ('S1','S2','S3')), seed_hash text NOT NULL, enabled boolean NOT NULL DEFAULT true, FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id), UNIQUE(tenant_id,company_id,id));
CREATE TABLE mock_scenario_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, scenario_id uuid NOT NULL, event_index integer NOT NULL CHECK(event_index>=0), event_kind text NOT NULL CHECK(event_kind IN ('MOCK_RESPONSE','APPROVAL_DECISION','EVIDENCE_CORRECTION','INFORMATION_GAP')), payload jsonb NOT NULL, seeded_principal_id uuid NOT NULL, consumed_at timestamptz, inbox_id uuid, FOREIGN KEY(tenant_id,company_id,scenario_id) REFERENCES mock_scenario(tenant_id,company_id,id), FOREIGN KEY(tenant_id,seeded_principal_id) REFERENCES principal(tenant_id,id), FOREIGN KEY(tenant_id,company_id,inbox_id) REFERENCES inbox(tenant_id,company_id,id), UNIQUE(scenario_id,event_index), UNIQUE(tenant_id,company_id,id));
CREATE TABLE state_transition (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, case_id uuid NOT NULL, task_id uuid, from_state text NOT NULL, to_state text NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,case_id) REFERENCES business_case(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,task_id) REFERENCES task(tenant_id,company_id,id), FOREIGN KEY(tenant_id,actor_id) REFERENCES principal(tenant_id,id));
CREATE TABLE audit_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, company_id uuid NOT NULL, principal_id uuid NOT NULL, request_id uuid NOT NULL, action text NOT NULL, object_type text NOT NULL, object_id uuid NOT NULL, before_hash text, after_hash text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id), FOREIGN KEY(tenant_id,principal_id) REFERENCES principal(tenant_id,id));
CREATE INDEX task_due ON task(tenant_id,company_id,next_attempt_at,due_at) WHERE state IN ('PENDING','READY','WAITING_RESPONSE');
CREATE INDEX outbox_ready ON outbox(available_at) WHERE state IN ('PENDING','LEASED');
CREATE INDEX timer_due ON timer(fire_at) WHERE state='SCHEDULED';
CREATE INDEX evidence_case ON evidence(tenant_id,company_id,case_id,observed_at);
CREATE INDEX task_case ON task(tenant_id,company_id,case_id,state);
CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_RECORD' USING ERRCODE='55000'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['source_document','intake_row','evidence','evidence_lineage','policy_snapshot','approval_decision','audit_event','state_transition','quantity_movement'] LOOP EXECUTE format('CREATE TRIGGER immutable_guard BEFORE UPDATE OR DELETE ON aurora.%I FOR EACH ROW EXECUTE FUNCTION aurora.immutable_row()',t); END LOOP; END $$;

-- Cross-object invariants: approvals cannot be attached to another plan/action/revision.
ALTER TABLE auth_session ADD UNIQUE(tenant_id,principal_id,id);
ALTER TABLE approval_decision ADD FOREIGN KEY(tenant_id,principal_id,session_id) REFERENCES auth_session(tenant_id,principal_id,id);
ALTER TABLE source_document ADD UNIQUE(tenant_id,company_id,id,source_ref);
ALTER TABLE intake_row ADD FOREIGN KEY(tenant_id,company_id,document_id,source_ref) REFERENCES source_document(tenant_id,company_id,id,source_ref);
ALTER TABLE action_plan ADD UNIQUE(tenant_id,company_id,id,revision);
ALTER TABLE plan_action ADD UNIQUE(tenant_id,company_id,plan_id,id);
ALTER TABLE approval_requirement ADD FOREIGN KEY(tenant_id,company_id,plan_id,action_id) REFERENCES plan_action(tenant_id,company_id,plan_id,id);
ALTER TABLE approval_scope ADD FOREIGN KEY(tenant_id,company_id,plan_id,action_id) REFERENCES plan_action(tenant_id,company_id,plan_id,id);
ALTER TABLE approval_scope ADD FOREIGN KEY(tenant_id,company_id,plan_id,revision) REFERENCES action_plan(tenant_id,company_id,id,revision);
ALTER TABLE task ADD FOREIGN KEY(tenant_id,company_id,plan_id,action_id) REFERENCES plan_action(tenant_id,company_id,plan_id,id);
ALTER TABLE command ADD FOREIGN KEY(tenant_id,company_id,plan_id,action_id) REFERENCES plan_action(tenant_id,company_id,plan_id,id);
CREATE TABLE ai_run_evidence (tenant_id uuid NOT NULL, company_id uuid NOT NULL, ai_run_id uuid NOT NULL, evidence_id uuid NOT NULL, PRIMARY KEY(ai_run_id,evidence_id), FOREIGN KEY(tenant_id,company_id,ai_run_id) REFERENCES ai_run(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,evidence_id) REFERENCES evidence(tenant_id,company_id,id));
CREATE FUNCTION fixed_plan_content() RETURNS trigger LANGUAGE plpgsql AS $fixed$ BEGIN
IF (to_jsonb(NEW)-'state'-'version') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'version') THEN RAISE EXCEPTION 'PLAN_REVISION_REQUIRED' USING ERRCODE='55000'; END IF; RETURN NEW; END $fixed$;
CREATE TRIGGER fixed_plan BEFORE UPDATE ON action_plan FOR EACH ROW EXECUTE FUNCTION fixed_plan_content();
CREATE TRIGGER immutable_action BEFORE UPDATE OR DELETE ON plan_action FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_requirement BEFORE UPDATE OR DELETE ON approval_requirement FOR EACH ROW EXECUTE FUNCTION immutable_row();

-- SET LOCAL is supplied only from authenticated server middleware, never from client headers.
CREATE FUNCTION company_access(t uuid,c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=aurora,pg_temp AS $$ SELECT t=nullif(current_setting('aurora.tenant_id',true),'')::uuid AND EXISTS (SELECT 1 FROM company_role r JOIN principal p ON p.id=r.principal_id AND p.tenant_id=r.tenant_id WHERE r.tenant_id=t AND r.company_id=c AND r.principal_id=nullif(current_setting('aurora.principal_id',true),'')::uuid AND p.enabled) $$;
DO $$ DECLARE t text; BEGIN FOR t IN SELECT table_name FROM information_schema.columns WHERE table_schema='aurora' AND column_name='company_id' AND table_name <> 'company_role' LOOP EXECUTE format('ALTER TABLE aurora.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE aurora.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY company_isolation ON aurora.%I USING (aurora.company_access(tenant_id,company_id)) WITH CHECK (aurora.company_access(tenant_id,company_id))',t); END LOOP; END $$;
-- Identity/bootstrap tables deliberately not exposed as generic CRUD. Runtime SELECT only
-- through narrow auth module; no public SELECT/INSERT on company_role/principal/auth_session.
REVOKE ALL ON ALL TABLES IN SCHEMA aurora FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA aurora FROM PUBLIC;
